// Unit tests for the component-identity report core (version.hpp): the two
// binary-output parsers and the renderer. Pure -- no subprocess, no git.
//
// Run by tests/andes_sim/test_andes_sim_version.sh and scripts/test_all.sh.
#include <string>

#include "test_check.hpp"
#include "version.hpp"

using andes_sim::EngineVersion;
using andes_sim::format_version_report;
using andes_sim::parse_engine_version;
using andes_sim::parse_qemu_version;
using andes_sim::VersionReport;

int main() {
  // ---- QEMU: `qemu-system-riscv64 --version` -----------------------------
  {
    CHECK(parse_qemu_version(
              "QEMU emulator version 10.2.3\n"
              "Copyright (c) 2003-2025 Fabrice Bellard and the QEMU Project "
              "developers\n") == "10.2.3");
    // Distribution builds suffix the number; the bare number is what we want.
    CHECK(parse_qemu_version("QEMU emulator version 8.2.1 (v8.2.1-dirty)\n") ==
          "8.2.1");
    // Nothing usable -> empty, so the caller renders "unknown".
    CHECK(parse_qemu_version("").empty());
    CHECK(parse_qemu_version("bash: qemu-system-riscv64: not found\n").empty());
    // The word alone, with no number after it, is not a version.
    CHECK(parse_qemu_version("version\n").empty());
  }

  // ---- engine: `sim_<cfg> --version` -------------------------------------
  {
    CHECK(parse_engine_version(
              "Copyright (C) 2013-2026 Andes Technology Corporation. All "
              "rights reserved.\n"
              "Version : 87a0baa\n\n") == "87a0baa");
    CHECK(parse_engine_version("Version: 9b01c20\n") == "9b01c20");
    CHECK(parse_engine_version("").empty());
    CHECK(parse_engine_version("Version :\n").empty());
    // A line that merely mentions the word is not the version line.
    CHECK(parse_engine_version("no version here\n").empty());
  }

  // ---- the rendered report ------------------------------------------------
  {
    VersionReport r;
    r.release = "v0.1.0";
    r.andesim = "llamacpp/437da16";
    r.abi = "main/9ecc0cc";
    r.qemu = "10.2.3";
    r.engines = {{"vsim:ax46mpv_fpga_l3", "87a0baa"}};
    CHECK(format_version_report(r) ==
          "AndeSim   v0.1.0 (llamacpp/437da16)\n"
          "  abi     main/9ecc0cc\n"
          "  qemu    10.2.3\n"
          "  engine  87a0baa (vsim:ax46mpv_fpga_l3)\n");
  }

  // Every engine binary in use gets its own line, so a mixed-version install
  // is visible rather than hidden behind one arbitrary pick.
  {
    VersionReport r;
    r.release = "v0.1.0";
    r.andesim = "llamacpp/437da16";
    r.abi = "main/9ecc0cc";
    r.qemu = "10.2.3";
