// `andesim --version` -- the identity of every bundled component.
//
// AndeSim ships as four separately-built pieces: this driver, the shared ABI
// headers it was compiled against, a QEMU binary, and a cycle-accurate engine
// binary. An install can mix versions of them, so a bug report has to be able
// to name all four.
//
// The two halves are versioned by different means, on purpose:
//   * driver + ABI are built together, so their git identity is stamped into
//     the binary at build time (cmake/build_stamp.cmake -> build_stamp.h);
//   * QEMU and the engine arrive as PREBUILT binaries, so only the binaries
//     themselves can say what they are -- they are asked at run time. A
//     prebuilt binary can be older than the source tree it sits in, and that
//     difference is exactly what this report exists to expose.
//
// This header is the pure core: the two output parsers and the renderer. The
// collection side (git stamp + subprocess probes) lives in cmd_version.cpp.
#ifndef ANDESIM_VERSION_HPP
#define ANDESIM_VERSION_HPP

#include <string>
#include <string_view>
#include <vector>

namespace andes_sim {

// One engine binary's self-report. `version` empty => the binary could not be
// asked, or did not answer.
struct EngineVersion {
  std::string id;       // the engine id, e.g. "vsim:ax46mpv_fpga_l3"
  std::string version;  // what the binary reported, e.g. "87a0baa"
};

// Every component's identity. Empty fields render as "unknown" -- a component
// that cannot be reached is reported, never dropped, and never fatal.
struct VersionReport {
  std::string release;   // the AndeSim release (SemVer tag), e.g. "v0.1.0"
  std::string andesim;   // "<branch>/<short commit>" of the andesim checkout
  std::string abi;       // "<branch>/<short commit>" of the shared ABI headers
  std::string qemu;      // QEMU's own reported version, e.g. "10.2.3"
  std::string qemu_bin;  // the binary asked (shown only when it did not answer)
  std::vector<EngineVersion> engines;  // every engine binary in use
};

// `qemu-system-riscv64 --version` output -> the bare version number
// ("QEMU emulator version 10.2.3" -> "10.2.3"). "" when the text carries none.
std::string parse_qemu_version(std::string_view out);

// `sim_<cfg> --version` output -> the engine's self-reported version
// ("Version : 87a0baa" -> "87a0baa"). "" when the text carries none.
std::string parse_engine_version(std::string_view out);

// Render the report: one labelled line per component, newline-terminated.
std::string format_version_report(const VersionReport& r);

}  // namespace andes_sim

#endif  // ANDESIM_VERSION_HPP

