#include "version.hpp"

#include <cctype>

namespace andes_sim {
namespace {

constexpr std::string_view kUnknown = "unknown";
constexpr size_t kLabelWidth = 9;  // widest label ("  engine") + padding

bool is_space(char c) { return std::isspace(static_cast<unsigned char>(c)); }

// [begin, end) of the whitespace-delimited token starting at or after `pos`;
// begin == end == npos when only whitespace remains.
std::string_view next_token(std::string_view s, size_t& pos) {
  while (pos < s.size() && is_space(s[pos])) ++pos;
  const size_t b = pos;
  while (pos < s.size() && !is_space(s[pos])) ++pos;
  return s.substr(b, pos - b);
}

std::string_view trim(std::string_view s) {
  size_t b = 0, e = s.size();
  while (b < e && is_space(s[b])) ++b;
  while (e > b && is_space(s[e - 1])) --e;
  return s.substr(b, e - b);
}

// `value` when the component answered, else "unknown"; `note` (when non-empty)
// is appended in parentheses -- which binary was asked, or why it is unknown.
std::string cell(std::string_view value, std::string_view note) {
  std::string s{value.empty() ? kUnknown : value};
  if (!note.empty()) {
    s += " (";
    s += note;
    s += ')';
  }
  return s;
}

void row(std::string& out, std::string_view label, const std::string& value) {
  out += label;
  out.append(label.size() < kLabelWidth ? kLabelWidth - label.size() : 0, ' ');
  out += value;
  out += '\n';
}

}  // namespace

// QEMU prints "QEMU emulator version 10.2.3 [(extra)]". Take the token after
// the word "version", and only when it looks like a number -- so a line that
// merely mentions the word yields nothing rather than a bogus value.
std::string parse_qemu_version(std::string_view out) {
  for (size_t pos = 0;;) {
    std::string_view tok = next_token(out, pos);
    if (tok.empty()) return "";
    if (tok != "version") continue;
    std::string_view val = next_token(out, pos);
    if (!val.empty() && std::isdigit(static_cast<unsigned char>(val[0])))
      return std::string{val};
  }
}

// The engine prints a copyright banner then "Version : <commit>". Take the
// text after the colon of the line whose first token is "Version".
std::string parse_engine_version(std::string_view out) {
  for (size_t pos = 0; pos < out.size();) {
    const size_t eol = out.find('\n', pos);
    std::string_view line =
        out.substr(pos, eol == std::string_view::npos ? eol : eol - pos);
    pos = (eol == std::string_view::npos) ? out.size() : eol + 1;

    std::string_view t = trim(line);
    if (!t.starts_with("Version")) continue;
    const size_t colon = t.find(':');
    if (colon == std::string_view::npos) continue;
    std::string_view val = trim(t.substr(colon + 1));
    if (!val.empty()) return std::string{val};
  }
  return "";
}

std::string format_version_report(const VersionReport& r) {
  std::string out;
  row(out, "AndeSim", cell(r.release, r.andesim.empty() ? kUnknown : r.andesim));
  row(out, "  abi", cell(r.abi, ""));
  // The QEMU binary's path is worth showing only when it did not answer.
  row(out, "  qemu", cell(r.qemu, r.qemu.empty() ? r.qemu_bin : ""));
  if (r.engines.empty())
    row(out, "  engine", cell("", "no engine binary found"));
  for (const EngineVersion& e : r.engines)
    row(out, "  engine", cell(e.version, e.id));
  return out;
}

}  // namespace andes_sim

