input.content:
// `andesim --version` -- collect and print the identity of every bundled
// component. See version.hpp for why the four are versioned by different means.
//
// The build-time half comes from build_stamp.h, regenerated on every build. The
// run-time half is asked of the binaries actually in use: a prebuilt QEMU or
// engine can be older than the source tree it sits in, so only the binary can
// say what it is. Nothing here can fail the command -- a binary that is absent
// or silent leaves its field empty, which renders "unknown".
#include <cstdio>
#include <string>
#include <string_view>

#include "build_stamp.h"
#include "engine_registry.hpp"
#include "process.hpp"
#include "version.hpp"

namespace andes_sim {
namespace {

constexpr int kProbeTimeoutMs = 5000;

// Ask one binary for its own version; "" when it cannot be reached, hangs, or
// says nothing usable. `parse` lifts the value out of that binary's wording.
std::string ask(const std::string& bin,
                std::string (*parse)(std::string_view)) {
  if (bin.empty()) return "";
  RunResult r = run_process({bin, "--version"}, kProbeTimeoutMs);
  if (r.spawn_failed || r.timed_out) return "";
  return parse(r.out);
}

}  // namespace

int cmd_version() {
  VersionReport rep;
  rep.release = ANDESIM_RELEASE;
  rep.andesim = ANDESIM_GIT_ID;
  rep.abi = ANDESIM_ABI_GIT_ID;

  rep.qemu_bin = builtin_qemu().bin_path;
  rep.qemu = ask(rep.qemu_bin, parse_qemu_version);

  // Every cycle-accurate engine that discovery finds -- the same binaries a run
  // would use. QEMU has its own line, so the functional engines are skipped.
  const Discovery disc = discover_engines();
  for (const EngineDescriptor& e : disc.engines) {
    if (e.kind != "cycle-accurate") continue;
    rep.engines.push_back({e.id, ask(e.bin_path, parse_engine_version)});
  }

  std::fputs(format_version_report(rep).c_str(), stdout);
  return 0;
}

}  // namespace andes_sim

